import{_ as e,o as a,c as t,ae as r}from"./chunks/framework.Bwt6MOeu.js";const p=JSON.parse('{"title":"Academy Guardian Rights, Sensitive Reports, and Escalation","description":"","frontmatter":{},"headers":[],"relativePath":"guide/academy-guardian-rights-sensitive-reports-and-escalation.md","filePath":"guide/academy-guardian-rights-sensitive-reports-and-escalation.md"}'),n={name:"guide/academy-guardian-rights-sensitive-reports-and-escalation.md"};function s(o,i,l,d,u,c){return a(),t("div",null,[...i[0]||(i[0]=[r('<h1 id="academy-guardian-rights-sensitive-reports-and-escalation" tabindex="-1">Academy Guardian Rights, Sensitive Reports, and Escalation <a class="header-anchor" href="#academy-guardian-rights-sensitive-reports-and-escalation" aria-label="Permalink to &quot;Academy Guardian Rights, Sensitive Reports, and Escalation&quot;">​</a></h1><p>This document explains how Academy handles guardian-linked participation, sensitive reports, and escalation pathways.</p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Academy is designed to support guardian visibility where appropriate without eliminating the need for protected reporting pathways. This document explains how those two goals coexist.</p><h2 id="guardian-rights" tabindex="-1">Guardian rights <a class="header-anchor" href="#guardian-rights" aria-label="Permalink to &quot;Guardian rights&quot;">​</a></h2><p>Where Academy participation is guardian-linked, guardians may have visibility into relevant participation, scheduling, and policy-linked interactions.</p><p>Guardian-linked visibility is intended to:</p><ul><li>support safety and transparency</li><li>clarify responsibility and consent</li><li>make oversight explicit rather than informal</li></ul><h2 id="limits-of-ordinary-visibility" tabindex="-1">Limits of ordinary visibility <a class="header-anchor" href="#limits-of-ordinary-visibility" aria-label="Permalink to &quot;Limits of ordinary visibility&quot;">​</a></h2><p>Ordinary visibility is not always appropriate for every report or every safety scenario.</p><p>Some reports require restricted handling because immediate broad visibility could:</p><ul><li>place a participant at risk</li><li>interfere with review</li><li>expose a sensitive safeguarding issue prematurely</li></ul><h2 id="sensitive-reports" tabindex="-1">Sensitive reports <a class="header-anchor" href="#sensitive-reports" aria-label="Permalink to &quot;Sensitive reports&quot;">​</a></h2><p>Sensitive reports include situations involving:</p><ul><li>coercion</li><li>boundary violations</li><li>harmful conduct</li><li>abuse concerns</li><li>guardian-linked or household-linked risk</li><li>situations requiring a safeguarding review before normal disclosure</li></ul><p>Sensitive reports must be handled through a documented safeguarding pathway rather than the ordinary review path.</p><h2 id="escalation-model" tabindex="-1">Escalation model <a class="header-anchor" href="#escalation-model" aria-label="Permalink to &quot;Escalation model&quot;">​</a></h2><p>Academy must support a documented escalation path for:</p><ul><li>review</li><li>intervention</li><li>restricted handling</li><li>further escalation when required by policy or law</li></ul><p>This escalation path must be attributable, reviewable, and bounded by the human-first charter.</p><h2 id="human-first-requirement" tabindex="-1">Human-first requirement <a class="header-anchor" href="#human-first-requirement" aria-label="Permalink to &quot;Human-first requirement&quot;">​</a></h2><p>Guardian-linked participation does not override the system’s duty to protect human beings. Where ordinary visibility conflicts with documented safeguarding requirements, the safeguarding path takes priority.</p><h2 id="related-documents" tabindex="-1">Related documents <a class="header-anchor" href="#related-documents" aria-label="Permalink to &quot;Related documents&quot;">​</a></h2><ul><li>Academy Safeguarding and Minor Protection</li><li>Academy Interaction Contract</li><li>Privacy</li><li>Terms</li></ul>',24)])])}const m=e(n,[["render",s]]);export{p as __pageData,m as default};
